class Solution {
public:
    std::string decodeMessage(std::string key, std::string message) {
        std::vector<char> table(26, 0);
        char cur = 'a';
        for (char ch : key) {
            if (ch >= 'a' && ch <= 'z' && table[ch - 'a'] == 0) {
                table[ch - 'a'] = cur++;
            }
        }
        for (char& ch : message) {
            if (ch >= 'a' && ch <= 'z') {
                ch = table[ch - 'a'];
            }
        }
        return message;
    }
};

class Solution {
    public String decodeMessage(String key, String message) {
        char[] table = new char[26];
        char cur = 'a';
        for (int i = 0; i < key.length(); ++i) {
            char ch = key.charAt(i);
            if (ch >= 'a' && ch <= 'z' && table[ch - 'a'] == 0) {
                table[ch - 'a'] = cur++;
            }
        }
        char[] res = message.toCharArray();
        for (int i = 0; i < res.length; ++i) {
            if (res[i] >= 'a' && res[i] <= 'z') {
                res[i] = table[res[i] - 'a'];
            }
        }
        return new String(res);
    }
}

var decodeMessage = function(key, message) {
    const map = new Map();
    map.set(' ', ' ');
    let cur = 97;
    for (const ch of key) {
        if (ch !== ' ' && !map.has(ch)) {
            map.set(ch, String.fromCharCode(cur++));
        }
    }
    return message.split('').map(ch => map.get(ch)).join('');
};
